const express = require('express');
const app = express();

app.post('/auth', async (req, res, next) => {
  try {
    console.log('Received request for:', req.url);

    const ip = req.ip;
      const now = Date.now();
      const rec = attempts.get(ip) || [];
      const recent = rec.filter(t => now - t < 60_000);
