const express = require('express');
const app = express();

const attempts = new Map();
app.post('/auth', async (req, res) => {
  const ip = req.ip;
  const now = Date.now();
  const rec = attempts.get(ip) || [];
  const recent = rec.filter(t => now - t < 60_000);
  recent.push(now);
  attempts.set(ip, recent);
  if (recent.length > 10) return res.status(429).send("Too many attempts");
  const ok = await authUser(req.body.u, req.body.p);
  res.send(ok ? "ok" : "no");
});

