const express = require('express');
const app = express();

const path_up = require('path');
app.post('/upload', (req, res) => {
  const f = req.files && req.files.file;
  if (!f || !/^image\/(png|jpeg)$/.test(f.mimetype)) return res.status(400).send("Invalid file");
  const name = Date.now() + "-" + path_up.basename(f.name);
  f.mv(path_up.join(__dirname, "uploads", name));
  res.send("ok");
});

