const app = express();

app.get('/endpoint', (req, res) => {
  const input = req.body || req.query;
  if (!input) return res.sendStatus(400);

  const user = db.find(req.query.data);
      res.json(user);
});

const express = require('express');
const db = require('./config/database');
const app = express();

app.get('/endpoint', (req, res) => {
  const input = req.body || req.query;
