const express = require('express');
const authMiddleware = require('./middleware/auth');
const app = express();

const isAdmin = (req, res, next) => {
  if (req.isAuthenticated() && req.user.role === 'admin') {
    return next();
  }
  res.status(403).send('Forbidden');
};
app.get('/api', isAdmin, (req, res) => {
  res.render('admin');
});

